import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DMvgf4hZ.js";const k=JSON.parse('{"title":"多语言维护","description":"","frontmatter":{},"headers":[],"relativePath":"development/i18n.md","filePath":"development/i18n.md","lastUpdated":1794745517000}'),l={name:"development/i18n.md"};function o(r,e,n,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="多语言维护" tabindex="-1">多语言维护 <a class="header-anchor" href="#多语言维护" aria-label="Permalink to &quot;多语言维护&quot;">​</a></h1><p>语言字典与翻译运行时集中在 <a href="https://github.com/dolfly/toonflow/blob/master/packages/i18n/readme.md" target="_blank" rel="noreferrer">packages/i18n</a>。Web 的明确展示位置由 Vite 插件在编译时转换，业务源码可继续使用中文；动态文案使用 <code>t</code> / <code>msg</code> 标签模板。服务端使用请求语言上下文，避免并发请求之间串语言。</p><h2 id="修改文案的流程" tabindex="-1">修改文案的流程 <a class="header-anchor" href="#修改文案的流程" aria-label="Permalink to &quot;修改文案的流程&quot;">​</a></h2><ol><li><p>修改中文源文案。</p></li><li><p>手动执行抽取命令：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/i18n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract</span></span></code></pre></div></li><li><p>补齐 <code>packages/i18n/src/locales/</code> 中各语言的同名键，保留占位符。</p></li></ol><p>开发启动和构建不会自动抽取，也不会自动生成译文。</p><h2 id="规则与边界" tabindex="-1">规则与边界 <a class="header-anchor" href="#规则与边界" aria-label="Permalink to &quot;规则与边界&quot;">​</a></h2><ul><li>翻译仅用于显示，不改变用户数据、模型正文或业务判断值。</li><li>供应商、tools、nodes、节点脚手架子包及安装器不在翻译范围内。</li><li>抽取只生成中文源文案和来源索引，不生成其他语言的译文。</li></ul><p>具体用法、语言回退规则和验证记录见<a href="https://github.com/dolfly/toonflow/blob/master/packages/i18n/readme.md" target="_blank" rel="noreferrer">多语言维护说明</a>与<a href="https://github.com/dolfly/toonflow/blob/master/packages/i18n/regression.md" target="_blank" rel="noreferrer">多语言回归记录</a>。</p>',8)])])}const m=a(l,[["render",o]]);export{k as __pageData,m as default};
